import { canonicalSha256 } from '../core/canonical-json.mjs';
import { classifyMaturity } from './maturity.mjs';
const TRUSTED_JUDGE=Symbol('forgeos.trusted-semantic-judge-v2');
function finite(value,fallback=0){return Number.isFinite(Number(value))?Number(value):fallback;}
function mean(values){return values.length?values.reduce((a,b)=>a+b,0)/values.length:0;}
function confidence(values,z=1.96){if(!values.length)return{low:0,high:0};if(values.length===1)return{low:values[0],high:values[0]};const average=mean(values);const variance=values.reduce((sum,value)=>sum+(value-average)**2,0)/(values.length-1);const margin=z*Math.sqrt(variance/values.length);return{low:average-margin,high:average+margin};}
function weightedScore(rubric,items){let weighted=0,total=0;for(const [id,rule] of Object.entries(rubric??{})){const weight=finite(rule.weight,0);const value=Math.max(0,Math.min(100,finite(items?.[id],0)));weighted+=value*weight;total+=weight;}return total?weighted/total:0;}
function sanitizeOutput(output){return{text:String(output?.text??''),structuredContent:output?.structuredContent??null,tokens:Number.isInteger(output?.tokens)&&output.tokens>=0?output.tokens:0,outputSha256:canonicalSha256({text:String(output?.text??''),structuredContent:output?.structuredContent??null,tokens:Number.isInteger(output?.tokens)&&output.tokens>=0?output.tokens:0})};}
export class TrustedSemanticJudge{constructor({id,trustDomain,score}){if(!id||!trustDomain||typeof score!=='function')throw new TypeError('Judge id, trustDomain, and score are required');this.id=String(id);this.trustDomain=String(trustDomain);this.score=score;Object.defineProperty(this,TRUSTED_JUDGE,{value:true});}}
async function evaluateRow({caseDefinition,seed,mode,producer,checks,judges,skill}){const raw=await producer({caseDefinition:structuredClone(caseDefinition),seed,mode,skill:structuredClone(skill)});const output=sanitizeOutput(raw);const deterministic=[];for(const check of checks){const result=await check({caseDefinition:structuredClone(caseDefinition),output:structuredClone(output),seed,mode});if(!result?.id)throw new TypeError('Deterministic check requires id');deterministic.push({id:String(result.id),passed:result.passed===true,metrics:structuredClone(result.metrics??{}),evidence:[...(result.evidence??[])]});}const semantic=[];for(const judge of judges){if(judge[TRUSTED_JUDGE]!==true)throw new Error('Untrusted semantic judge');if(judge.trustDomain===skill.authorTrustDomain)throw new Error('Semantic judge must be independent from skill author trust domain');const result=await judge.score({caseDefinition:structuredClone(caseDefinition),output:structuredClone(output),seed,mode,skillId:skill.id});const items=structuredClone(result?.items??{});semantic.push({judgeId:judge.id,trustDomain:judge.trustDomain,items,quality:weightedScore(caseDefinition.rubric,items),uncertainty:Math.max(0,Math.min(1,finite(result?.uncertainty,1))),evidenceSpans:[...(result?.evidenceSpans??[])]});}const deterministicPassed=deterministic.every((item)=>item.passed);const quality=mean(semantic.map((item)=>item.quality));return{caseId:caseDefinition.id,seed,mode,output,deterministic,deterministicPassed,quality,judgeScores:semantic,rowSha256:canonicalSha256({caseId:caseDefinition.id,seed,mode,output,deterministic,semantic})};}
function summary(rows){return{samples:rows.length,passRate:mean(rows.map((row)=>Number(row.deterministicPassed))),quality:mean(rows.map((row)=>row.quality)),tokens:rows.reduce((sum,row)=>sum+row.output.tokens,0),criticalFailures:rows.filter((row)=>!row.deterministicPassed).length};}
function paired(baseline,candidate){const map=new Map(baseline.map((row)=>[`${row.caseId}:${row.seed}`,row]));const quality=[],pass=[];for(const row of candidate){const base=map.get(`${row.caseId}:${row.seed}`);if(!base)throw new Error('Eval matrices differ');quality.push(row.quality-base.quality);pass.push(Number(row.deterministicPassed)-Number(base.deterministicPassed));}return{samples:quality.length,qualityDelta:{mean:mean(quality),confidence95:confidence(quality)},passDelta:{mean:mean(pass),confidence95:confidence(pass)}};}
function agreement(rows,judges){const values=[];for(const row of rows){const scores=row.judgeScores.map((item)=>item.quality);if(scores.length>1)values.push(Math.max(...scores)-Math.min(...scores));}return{judges:judges.length,meanAbsoluteSpread:mean(values),maximumSpread:values.length?Math.max(...values):0};}
export async function runSkillEvaluationV2({skill,cases,seeds=[1,2,3],producer,deterministicChecks=[],judges=[],policy={}}){if(!skill?.id||!skill?.version||!skill?.authorTrustDomain)throw new TypeError('Skill identity and author trust domain are required');if(!cases?.length||!seeds?.length)throw new TypeError('Eval cases and seeds are required');if(typeof producer!=='function'||!deterministicChecks.length||!judges.length)throw new TypeError('Producer, deterministic checks, and judges are required');const baseline=[],candidate=[];for(const caseDefinition of [...cases].sort((a,b)=>a.id.localeCompare(b.id)))for(const seed of [...seeds]){baseline.push(await evaluateRow({caseDefinition,seed,mode:'baseline',producer,checks:deterministicChecks,judges,skill}));candidate.push(await evaluateRow({caseDefinition,seed,mode:'candidate',producer,checks:deterministicChecks,judges,skill}));}const baselineSummary=summary(baseline),candidateSummary=summary(candidate),pairedResult=paired(baseline,candidate);const blockers=[];if(candidateSummary.criticalFailures>0)blockers.push(`deterministic-failure:${candidateSummary.criticalFailures}`);const minimumSamples=Number(policy.minimumSamples??6);if(pairedResult.samples<minimumSamples)blockers.push('insufficient-samples');if(pairedResult.qualityDelta.confidence95.low<=0&&pairedResult.passDelta.confidence95.low<=0)blockers.push('non-positive-confidence-lower-bound');const growth=baselineSummary.tokens?candidateSummary.tokens/baselineSummary.tokens-1:0;if(growth>Number(policy.maximumTokenGrowth??.35)&&pairedResult.qualityDelta.mean<Number(policy.minimumQualityDelta??2))blockers.push('token-only-growth');const maturity=classifyMaturity({depthScore:Number(policy.depthScore??75),publicScenarios:pairedResult.samples,holdoutScenarios:Number(policy.holdoutScenarios??0),modelFamilies:Number(policy.modelFamilies??2),confidenceLowerBound:Math.max(pairedResult.qualityDelta.confidence95.low/100,pairedResult.passDelta.confidence95.low),criticalFailures:candidateSummary.criticalFailures,humanReviewed:Boolean(policy.humanReviewed),productionEvidence:Boolean(policy.productionEvidence)});const status=blockers.length?'quarantined':maturity==='experimental'||maturity==='candidate'?'validated':maturity;const subject={schemaVersion:2,skill:{id:skill.id,version:skill.version,authorTrustDomain:skill.authorTrustDomain},corpusSha256:canonicalSha256(cases),seeds:[...seeds],baseline:baselineSummary,candidate:candidateSummary,paired:pairedResult,judgeAgreement:agreement(candidate,judges),decision:{status,blockers,maturity},rows:{baseline,candidate},createdAt:new Date().toISOString()};return Object.freeze({...subject,evalRunSha256:canonicalSha256({...subject,createdAt:null})});}
